import subprocess,time,sys,json,os
from playwright.sync_api import sync_playwright
SP=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
srv=subprocess.Popen([sys.executable,"-m","http.server","8809","--bind","127.0.0.1"],cwd=SP+"/docs",stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL);time.sleep(1)
errs=[]
SEED="""()=>new Promise(r=>{localStorage.setItem('yd_settings',JSON.stringify({grade:7,name:'',newPerDay:10,maxPerDay:25,weekGoal:5}));localStorage.setItem('yd_daily',JSON.stringify({date:new Date().toISOString().slice(0,10),ids:['k1','k2','k3']}));['repairV10','schedV15','sheetFixV18','claudeTip'].forEach(k=>localStorage.setItem('yd_'+k,'1'));localStorage.setItem('yd_masterRule','2');localStorage.setItem('yd_aiKey','AIzaTESTKEY0123456789abcdef');
 const q=indexedDB.open('yanlis-defterim',1);q.onupgradeneeded=()=>{const d=q.result;d.createObjectStore('mistakes',{keyPath:'id'});d.createObjectStore('photos')};
 q.onsuccess=async()=>{const im=await fetch('data:image/jpeg;base64,').then(x=>x.blob());const buf=await im.arrayBuffer();
  const t=q.result.transaction(['mistakes','photos'],'readwrite');const s=t.objectStore('mistakes');t.objectStore('photos').put({t:'image/jpeg',b:buf},'ph1');
  s.put({id:'k1',subject:'mat',topic:'Rasyonel Sayılarla İşlemler ve Problemler',grade:7,correct:'C',mine:'D',note:'',qPhoto:{id:'ph1'},createdAt:1,date:'2026-10-20',stage:1,next:'2026-11-01',mastered:false,reviews:1});
  s.put({id:'k2',subject:'mat',topic:'Tam Sayılar',grade:7,correct:null,note:'(−4)·(+3) − (−8)÷(+2) = ?',createdAt:2,date:'2026-10-20',stage:0,next:'2026-11-20',mastered:false,reviews:0});
  s.put({id:'k3',subject:'fen',topic:'Kuvvet',grade:7,correct:'A',mine:'B',note:'',qPhoto:{id:'ph1'},createdAt:3,date:'2026-10-20',stage:0,next:'2026-11-01',mastered:false,reviews:1});
  t.oncomplete=()=>r()}})"""
INIT="""window.__shared=[];navigator.canShare=d=>true;navigator.share=async d=>{window.__shared.push({text:d.text,files:(d.files||[]).map(f=>f.name)});};"""
try:
  with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(viewport={"width":390,"height":844},device_scale_factor=2);ctx.add_init_script(INIT)
    ctx.grant_permissions(["clipboard-read","clipboard-write"],origin="http://127.0.0.1:8809")
    pg=ctx.new_page();pg.on("pageerror",lambda e:errs.append(str(e)));pg.on("console",lambda m:errs.append(m.text) if m.type=="error" else None)
    pg.goto("http://127.0.0.1:8809/");pg.evaluate(SEED);pg.reload();pg.wait_for_selector(".hero");pg.wait_for_timeout(1500)
    pg.click("button:has-text('Sonuçları gir')");pg.wait_for_selector("#results:not([hidden]) .resrow")
    rows=pg.locator("#results .resrow");print("rows:",rows.count())
    rows.nth(0).locator("button.bad").click();rows.nth(1).locator("button.ok").click();rows.nth(2).locator("button.bad").click()
    pg.click("#results .screen-foot button");pg.wait_for_selector("#day:not([hidden])",timeout=5000);pg.wait_for_timeout(300)
    print("1 day opened:",pg.inner_text("#day .screen-top h2"),"| items:",pg.eval_on_selector_all("#day .dayitem .item-topic","e=>e.map(x=>x.textContent)"))
    print("  buttons:",pg.eval_on_selector_all("#day .screen-body > .in > .btn","e=>e.map(x=>x.textContent)"))
    pg.screenshot(path=SP+"/tests/out/wrongs-day.png")
    pg.click("#day button:has-text(\"Hepsini Claude'da çöz\")");pg.wait_for_timeout(600)
    sh=pg.evaluate("()=>window.__shared");print("2 shared:",json.dumps(sh,ensure_ascii=False)[:900])
    pg.go_back();pg.wait_for_selector("#day",state="hidden");pg.wait_for_timeout(300);print("3 url:",pg.url)
    b.close()
finally: srv.terminate()
print("errors:",errs)
